{
  "vulnerable_symbols": [],
  "trigger": "安装或加载 event-stream@3.3.6 / flatmap-stream@0.1.1 时，包内恶意代码利用宿主 npm_package_description 解密执行，针对 Copay 环境窃取私钥。",
  "preconditions": [
    "依赖树中存在 flatmap-stream@0.1.1（通常由 event-stream@3.3.6 引入）",
    "运行在 Node.js 环境并加载该包",
    "宿主包 npm_package_description 与恶意代码预期目标匹配（Copay 相关）",
    "存在 bitcore-wallet-client/lib/credentials.js 等可被覆盖的钱包凭据模块",
    "网络可达 copayapi.host 或 111.90.151.134:8080 以回传窃取数据"
  ],
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "in_the_wild",
      "quote": "A new maintainer of the popular event-stream npm package added a malicious sub-dependency, flatmap-stream, that exfiltrated cryptocurrency wallet seeds from Copay-derived applications."
    }
  ],
  "fixed_version": "",
  "summary_zh": "flatmap-stream 0.1.1 是恶意包，随 event-stream 3.3.6 引入，可盗私钥，请移除。"
}
